@Autowired
private InsurancePolicyService policyService;

public BigDecimal calculateReimbursement(String region, MedicalFee fee) {
    InsurancePolicy policy = policyService.getPolicy(region, LocalDate.now());
    return policy.calculateReimbursement(fee);
}

@Service
public class InsuranceAuditService {

    @Autowired
    private AuditLogRepository auditLogRepository;

    public AuditResult audit(InsuranceClaim claim, String auditorId) {
        AuditLog log = new AuditLog();
        log.setClaimId(claim.getId());
        log.setAuditorId(auditorId);
        log.setAuditTime(LocalDateTime.now());

        try {
            AuditResult result = doAudit(claim);
            log.setResult(result.getStatus());
            log.setDetails(result.getDetails());
            return result;
        } finally {
            auditLogRepository.save(log);
        }
    }
}

public SettlementResult settle(InsuranceSettlementRequest request) {
    // 1. 合规性校验
    ComplianceCheckResult checkResult = complianceChecker.check(
        request.getPatient(),
        request.getFeeItems(),
        request.getInsuranceType()
    );

    if (!checkResult.isCompliant()) {
        return SettlementResult.rejected(checkResult.getViolations());
    }

    // 2. 执行结算
    return doSettlement(request);
}
